#include <bits/stdc++.h>
#include <sys/resource.h>
using namespace std;using U=__uint128_t;
array<U,72> adj,original;const U OLD=(U(1)<<70)-1;
U reach(int root,int radius){U seen=U(1)<<root,front=seen;for(int d=0;d<radius&&front;d++){U next=0;uint64_t lo=uint64_t(front),hi=uint64_t(front>>64);while(lo){int v=__builtin_ctzll(lo);lo&=lo-1;next|=adj[v];}while(hi){int v=64+__builtin_ctzll(hi);hi&=hi-1;next|=adj[v];}front=next&~seen;seen|=next;}return seen;}
int first(U x){uint64_t lo=uint64_t(x);return lo?__builtin_ctzll(lo):64+__builtin_ctzll(uint64_t(x>>64));}
double cpu(){rusage r;getrusage(RUSAGE_SELF,&r);return r.ru_utime.tv_sec+r.ru_utime.tv_usec*1e-6+r.ru_stime.tv_sec+r.ru_stime.tv_usec*1e-6;}
void V(const vector<int>&v){cout<<'[';for(size_t i=0;i<v.size();i++){if(i)cout<<',';cout<<v[i];}cout<<']';}
int main(int argc,char**argv){if(argc!=4)return 2;ifstream in(argv[1]);int n,m,u,v;in>>n>>m;if(n!=70||m!=105)return 3;vector<pair<int,int>>E;while(in>>u>>v){E.push_back({u,v});adj[u]|=U(1)<<v;adj[v]|=U(1)<<u;}if(E.size()!=105)return 4;original=adj;
uint64_t matchings=0,repairs=0,rejectRepair=0,configs=0,failA=0,failB=0,failOld=0,passHelpers=0;bool complete=true,hit=false,stop=false;vector<int> bestCuts,bestRepair,bestA,bestB,firstCuts,firstRepair,firstA,firstB;pair<int,int>firstOld={-1,-1};double limit=atof(argv[3]);
for(int i=0;i<105&&!stop;i++)for(int j=i+1;j<105&&!stop;j++){auto[a0,a1]=E[i];auto[b0,b1]=E[j];if(a0==b0||a0==b1||a1==b0||a1==b1)continue;for(int k=j+1;k<105&&!stop;k++){auto[c0,c1]=E[k];if(c0==a0||c0==a1||c0==b0||c0==b1||c1==a0||c1==a1||c1==b0||c1==b1)continue;if((matchings&127)==0&&cpu()>limit){complete=false;stop=true;break;}matchings++;vector<int>P={a0,a1,b0,b1,c0,c1};sort(P.begin(),P.end());array<U,72> cut=original;for(int e:{i,j,k}){auto[a,b]=E[e];cut[a]&=~(U(1)<<b);cut[b]&=~(U(1)<<a);}
for(int ri=0;ri<6&&!stop;ri++)for(int rj=ri+1;rj<6&&!stop;rj++){int r=P[ri],s=P[rj];if(cut[r]&(U(1)<<s)){rejectRepair++;continue;}repairs++;vector<int>Q;for(int t=0;t<6;t++)if(t!=ri&&t!=rj)Q.push_back(P[t]);for(int aa=1;aa<4&&!stop;aa++){configs++;vector<int>A={Q[0],Q[aa]},B;for(int t=1;t<4;t++)if(t!=aa)B.push_back(Q[t]);adj=cut;adj[r]|=U(1)<<s;adj[s]|=U(1)<<r;adj[70]|=U(1)<<71;adj[71]|=U(1)<<70;for(int x:A){adj[70]|=U(1)<<x;adj[x]|=U(1)<<70;}for(int x:B){adj[71]|=U(1)<<x;adj[x]|=U(1)<<71;}
if((reach(70,5)&OLD)!=OLD){failA++;continue;}if((reach(71,5)&OLD)!=OLD){failB++;continue;}passHelpers++;bool ok=true;for(int x=0;x<70;x++){U miss=OLD&~reach(x,5);if(miss){ok=false;failOld++;if(firstOld.first<0){firstOld={x,first(miss)};firstCuts={i,j,k};firstRepair={r,s};firstA=A;firstB=B;}break;}}if(ok){hit=true;complete=false;stop=true;bestCuts={i,j,k};bestRepair={r,s};bestA=A;bestB=B;}
}}}}
if(hit){ofstream out(string(argv[2])+"/graph_d3_D5_n72.edges");out<<"72 108\n";for(int a=0;a<72;a++)for(int b=a+1;b<72;b++)if(adj[a]&(U(1)<<b))out<<a<<' '<<b<<'\n';}
cout<<"{\"status\":\""<<(hit?"FOUND72":complete?"EXHAUSTIVE_FIXED_ADJACENT_REPAIR_RULE_NO72":"UNKNOWN_CPU_BUDGET")<<"\",\"complete\":"<<(complete?"true":"false")<<",\"hit\":"<<(hit?"true":"false")<<",\"matchings\":"<<matchings<<",\"valid_repair_choices\":"<<repairs<<",\"rejected_duplicate_repairs\":"<<rejectRepair<<",\"configurations\":"<<configs<<",\"first_failure_counts\":{\"helper70_old_R5\":"<<failA<<",\"helper71_old_R5\":"<<failB<<",\"old_old_R5\":"<<failOld<<"},\"both_helpers_all_old_PASS\":"<<passHelpers<<",\"first_old_failure\":{\"pair\":["<<firstOld.first<<','<<firstOld.second<<"],\"cut_edge_ids\":";V(firstCuts);cout<<",\"repair\":";V(firstRepair);cout<<",\"pins70\":";V(firstA);cout<<",\"pins71\":";V(firstB);cout<<"},\"hit_cut_edge_ids\":";V(bestCuts);cout<<",\"hit_repair\":";V(bestRepair);cout<<",\"hit_pins70\":";V(bestA);cout<<",\"hit_pins71\":";V(bestB);cout<<",\"gate_CPU_seconds\":"<<setprecision(12)<<cpu()<<"}\n";}
